<template><view class="card checkin-calendar"><view class="row between"><view><text class="eyebrow">把清晨，留给自己</text><text class="title">小时的打卡日历</text></view><CartoonArt kind="sun" label="早起小太阳"/></view>
 <view class="early-panel"><view class="grow"><text class="item-title">{{store.study.checked_in?(store.study.early_checked_in?'今天已早起打卡 ☀':'今天已日常打卡 ✓'):'去专注页，点一下就能打卡'}}</text><text class="muted">我的早起截止时间：{{store.settings.early_deadline||'09:00'}}</text></view></view>
 <view class="deadline-form"><text class="label">设置最晚打卡时间</text><view class="deadline-inputs"><input aria-label="截止小时" type="number" maxlength="2" v-model="hour"/><text>:</text><input aria-label="截止分钟" type="number" maxlength="2" v-model="minute"/><button class="secondary small" :disabled="store.busy" @click="saveDeadline">保存时间</button></view></view>
 <view class="month-switch"><button aria-label="上个月" @click="move(-1)">‹</button><text>{{month.replace('-',' 年 ')}} 月</text><button aria-label="下个月" :disabled="month>=today.slice(0,7)" @click="move(1)">›</button></view>
 <text v-if="error" class="muted">{{error}}</text><view v-else class="month-grid"><text v-for="w in weeks" :key="w" class="week">{{w}}</text><view v-for="n in offset" :key="'blank'+n"/><button v-for="n in count" :key="n" class="day-cell" :class="{checked:regular.has(dayKey(n)),early:earlyMap.has(dayKey(n)),today:dayKey(n)===today,chosen:selected===dayKey(n)}" @click="selected=dayKey(n)"><text>{{n}}</text><text class="stamp">{{earlyMap.has(dayKey(n))?'☀':regular.has(dayKey(n))?'✓':'·'}}</text></button></view>
 <view class="calendar-key"><text>✓ 日常打卡</text><text>☀ 早起打卡</text><text>本月早起 {{data.early.length}} 天</text></view><view v-if="selected" class="checkin-detail"><CartoonArt :kind="selectedRecord?.kind==='early'?'sun':'book'" label="打卡足迹"/><view><text class="title">{{selected}}</text><text class="detail-kind">{{selectedRecord?(selectedRecord.kind==='early'?'☀ 早起打卡':'✓ 日常打卡'):'这一天还没有打卡'}}</text><text v-if="selectedRecord" class="muted">打卡时间：{{localTime(selectedRecord.checked_at)}}（北京时间）</text><text v-if="selectedRecord?.deadline" class="muted">当天早起截止：{{selectedRecord.deadline}}</text></view></view><text class="calendar-note">专注页统一打卡：截止时间内为早起，之后为日常。当天首次打卡类型不再改变。</text>
 </view></template>
<script setup>
import {ref,computed,watch} from 'vue';import {onShow} from '@dcloudio/uni-app';import {store,act} from '../services/store';import {request,message} from '../services/api';import CartoonArt from './CartoonArt.vue';
const today=new Date(Date.now()+8*3600000).toISOString().slice(0,10),month=ref(today.slice(0,7)),hour=ref('09'),minute=ref('00'),selected=ref(''),data=ref({regular:[],early:[]}),error=ref(''),weeks=['一','二','三','四','五','六','日'];let version=0;
watch(()=>store.settings.early_deadline,v=>{[hour.value,minute.value]=(v||'09:00').split(':');},{immediate:true});
const regular=computed(()=>new Set(data.value.regular)),earlyMap=computed(()=>new Map(data.value.early.map(r=>[r.day,r]))),selectedRecord=computed(()=>data.value.records?.find(r=>r.day===selected.value)),count=computed(()=>new Date(Date.UTC(Number(month.value.slice(0,4)),Number(month.value.slice(5)),0)).getUTCDate()),offset=computed(()=>(new Date(month.value+'-01').getUTCDay()+6)%7);
const dayKey=n=>month.value+'-'+String(n).padStart(2,'0'),localTime=v=>new Date(Date.parse(v)+8*3600000).toISOString().slice(11,19);
function move(delta){const d=new Date(month.value+'-01');d.setUTCMonth(d.getUTCMonth()+delta);month.value=d.toISOString().slice(0,7);selected.value='';}
async function load(){const seq=++version;data.value={regular:[],early:[]};if(!store.user)return;try{const result=await request('/checkins/calendar?month='+month.value);if(seq===version){data.value=result;error.value='';}}catch(e){if(seq===version)error.value=e.message;}}
async function saveDeadline(){if(!/^\d{1,2}$/.test(hour.value)||!/^\d{1,2}$/.test(minute.value)||Number(hour.value)>23||Number(minute.value)>59)return message('请输入有效的小时和分钟');if(await act('/settings','PATCH',{early_deadline:String(hour.value).padStart(2,'0')+':'+String(minute.value).padStart(2,'0')}))message('早起截止时间已保存');}
watch([month,()=>store.user?.id,()=>store.study.checked_in,()=>store.study.early_checked_in],load,{immediate:true});onShow(load);
</script>
<style scoped>.checkin-calendar{background:#fffdf5}.early-panel{display:flex;align-items:center;gap:20rpx;padding:24rpx;border-radius:22rpx;background:#fff0bf;margin-bottom:20rpx}.early-panel .item-title{font-size:25rpx}.early-panel .muted{font-size:22rpx}.early-panel button{flex-shrink:0}.deadline-form{background:#fff8e8;border-radius:20rpx;padding:20rpx}.deadline-inputs{display:flex;align-items:center;gap:12rpx}.deadline-inputs input{width:80rpx;height:70rpx;text-align:center;padding:10rpx;margin:12rpx 0}.deadline-inputs button{margin-left:auto}.month-switch{display:flex;align-items:center;justify-content:space-between;margin:26rpx 0 20rpx;font-size:28rpx;font-weight:600}.month-switch button{padding:4rpx 24rpx;font-size:38rpx;background:#faecc9;color:#85632c}.month-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:10rpx}.week{text-align:center;font-size:22rpx;color:#a28a60;padding:8rpx}.day-cell{background:#faf5e9;padding:10rpx 0;color:#8a7454;font-size:25rpx;border:2rpx solid transparent;border-radius:16rpx}.stamp{display:block;font-size:19rpx;line-height:1.3;color:#b5a582}.day-cell.checked{background:#f5e6ba}.day-cell.early{background:#ffe39a}.day-cell.today{border-color:#d8ab4e}.day-cell.chosen{box-shadow:inset 0 0 0 2rpx #b99044}.calendar-key{display:flex;justify-content:space-between;gap:10rpx;font-size:21rpx;color:#9b7a42;margin-top:22rpx}.selected-note,.calendar-note{display:block;font-size:22rpx;color:#967f59;line-height:1.8;margin-top:16rpx}.calendar-note{font-size:20rpx}
</style>
<style scoped>.checkin-detail{display:flex;align-items:center;gap:24rpx;background:#fff0c7;border:2rpx solid #e6ce93;border-radius:24rpx;padding:28rpx;margin-top:24rpx}.checkin-detail .title{margin-bottom:8rpx}.detail-kind{display:block;color:#81612f;font-size:27rpx;margin-bottom:8rpx}.checkin-detail .cartoon-art{width:100rpx;height:100rpx}</style>
